table.insert(addon.quests[7790].description.variants, { "362:281723780:1304628883", "สกายบอร์นสองคนนี้ดูเหมือนถูกซ้อมจนตาย คนหนึ่งจมน้ำ อีกคนชุ่มไปด้วยเลือด ดูจากรูปลักษณ์แล้ว ทั้งคู่อาจเป็นญาติกันก็ได้ เป็นความอาฆาตระหว่างตระกูลหรือ? หรือการทรยศกันในครอบครัวที่อยู่คนละฝ่าย?\n\nเครื่องยศของฝ่าย Alliance และ Horde ที่ดูคุ้นตากระจัดกระจายอยู่ตามชายฝั่ง\n\nสำรวจต้นน้ำเพื่อหาเบาะแสเกี่ยวกับความตายที่ถูกกระแสน้ำพัดพามานี้" })
