table.insert(addon.quests[99215].description.variants, { "584:1140397140:1248657145", "<Ogunaro หรี่ตาลงขณะเจ้าเดินเข้าไปหา>\n\nLok'tar วอร์ล็อก ข้ายอมรับว่าประหลาดใจที่เห็นคนที่มี... พรสวรรค์แบบเจ้าอยู่ที่นี่\n\nหากเจ้ามาหาหมาป่าสำหรับขี่ ก็มาถูกที่แล้ว แต่จงรู้ไว้ว่าการขี่และผูกมิตรกับหมาป่าต่างจากการอัญเชิญอาชาเฟลอย่างที่เจ้าคุ้นเคย\n\nออร์คกับหมาป่าผูกพันกันด้วยสิ่งที่ลึกกว่าความอยากอวด ออร์คกับหมาป่าแต่ละคู่มีสายสัมพันธ์พิเศษที่มีค่ากว่าการซื้อขาย\n\nถ้าเจ้ามาเพื่อผูกสายสัมพันธ์กับหมาป่า ข้าแนะนำให้เดินไปดูทีละตัว หากรู้สึกถูกชะตากับตัวไหนก็กลับมาหาข้า" })
